INSERT INTO `webinar_tbl` (`title`, `hostname`, `host_pic`, `description`, `webinar_vid`, `webinar_id`, `webinar_link`, `schedule_date&time`, `status`, `is_published`, `subheading`, `subheading_size`, `subheading_bold`, `subheading_color`, `subheading_items_json`, `host_description`, `duration`, `timezone`) VALUES
('MIOYM Blueprint: A Startegic Approach to Residential Equity', 'Robert Costomiris', 0x75706c6f6164732f313737353530393933305f53637265656e73686f7420323032362d30342d3037203035303935392e706e67, 'Most real estate investors are competing for the same deals—and the same buyers. Most real estate ads talk about upside; we start with downside.\r\n\r\nMost real estate investments rely on long-term appreciation. We take a different approach. We focus on short-term single-family deals—buying below market, renovating, and reselling to first-time buyers in high-demand areas near New York City.\r\n\r\nThe goal isn\'t speculation—it\'s positioning inventory where demand already exists. By focusing exclusively on first-time homebuyers in supply-constrained neighborhoods, we’ve built a model designed for:\r\n\r\nReliable exit demand\r\n\r\nShorter hold periods\r\n\r\nTargeted ~15% annualized returns based on recent projects\r\n\r\nLearn how we:\r\n\r\nBuy below market\r\n\r\nUse conservative resale assumptions\r\n\r\nKeep short hold periods\r\n\r\nAvailable to accredited investors. If you’re an accredited investor, you can see one of our recent deals and how we structure returns.', 'uploads/1775578066_0330.mp4', 7, 'https://us06web.zoom.us/j/82118864926', '2026-10-21 13:00:00', 'upcoming', 1, 'Annualized returns-based on past history.\nSee how our model works during our 30 minute webinar where we break down the full numbers, timeline, and risk controls behind our investments.  focusing on Capital preservation, speed and predictability.\nFocused on acquiring , improving, and reselling homes to first time buyers in high demand under supplied markets.', 34, 1, '#ffffff', '[{\"text\":\"Annualized returns-based on past history.\",\"size\":34,\"spacing\":22,\"color\":\"#ffffff\",\"bold\":1,\"font\":\"system_sans\"},{\"text\":\"See how our model works during our 30 minute webinar where we break down the full numbers, timeline, and risk controls behind our investments.  focusing on Capital preservation, speed and predictability.\",\"size\":16,\"spacing\":4,\"color\":\"#f0b100\",\"bold\":1,\"font\":\"system_sans\"},{\"text\":\"Focused on acquiring , improving, and reselling homes to first time buyers in high demand under supplied markets.\",\"size\":16,\"spacing\":4,\"color\":\"#f0b100\",\"bold\":1,\"font\":\"system_sans\"}]', NULL, '45 min', 'America/New_York');
